void updateChartQuickBar(){
if(chartSymbolButton==null)return;
ArrayList<String> names=new ArrayList<>(getSharedPreferences(PREF,0).getStringSet("favorites",new HashSet<String>()));
if(names.isEmpty())names.addAll(allNames);Collections.sort(names,String.CASE_INSENSITIVE_ORDER);
String current=chartSymbol();int i=names.indexOf(current);
String prev=names.isEmpty()?"":names.get((i<0?0:(i-1+names.size())%names.size()));
String next=names.isEmpty()?"":names.get((i<0?0:(i+1)%names.size()));
chartPrevSymbolLabel.setText(prev.isEmpty()||prev.equals(current)?"":prev);
chartNextSymbolLabel.setText(next.isEmpty()||next.equals(current)?"":next);
chartPrevSymbolLabel.setAlpha(.48f);chartNextSymbolLabel.setAlpha(.48f);
chartSymbolButton.setText(current.isEmpty()?"Select market  ▾":current+"  ▾");
if(chartTfSpinner!=null&&chartTfSpinner.getSelectedItem()!=null)chartTimeframeLabel.setText(chartTfSpinner.getSelectedItem().toString()+"  ▾");
}
void showChartTimeframeMenu(){if(chartTfSpinner==null)return;android.widget.PopupMenu menu=new android.widget.PopupMenu(this,chartTimeframeLabel);String[] frames={"1m","3m","5m","15m","30m","1h","2h","4h","1d","1w"};for(int i=0;i<frames.length;i++)menu.getMenu().add(0,i,i,frames[i]);menu.setOnMenuItemClickListener(item->{chartTfSpinner.setSelection(item.getItemId());updateChartQuickBar();return true;});menu.show();}
void showChartSymbolPicker(){
LinearLayout box=column();box.setPadding(dp(14),dp(8),dp(14),0);EditText query=edit("Search Arcus markets…",1);box.addView(query);ListView results=new ListView(this);ArrayList<String> items=new ArrayList<>(allNames);Collections.sort(items,String.CASE_INSENSITIVE_ORDER);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_list_item_1,items){public View getView(int position,View convert,android.view.ViewGroup parent){TextView t=(TextView)super.getView(position,convert,parent);t.setTextColor(Color.WHITE);t.setPadding(dp(12),dp(10),dp(12),dp(10));return t;}};results.setAdapter(adapter);box.addView(results,new LinearLayout.LayoutParams(-1,dp(360)));query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence x,int st,int c,int a){}public void onTextChanged(CharSequence x,int st,int before,int count){String q=x.toString().trim().toLowerCase(Locale.ROOT);ArrayList<String> filtered=new ArrayList<>();for(String n:allNames)if(n.toLowerCase(Locale.ROOT).contains(q))filtered.add(n);adapter.clear();adapter.addAll(filtered);adapter.notifyDataSetChanged();}public void afterTextChanged(Editable e){}});AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Choose market").setView(box).setNegativeButton("Close",null).create();results.setOnItemClickListener((p,v,pos,id)->{String chosen=adapter.getItem(pos);dialog.dismiss();openChartFor(chosen);});dialog.show();
}
String chartSymbol(){return chartMarketSpinner==null||chartMarketSpinner.getSelectedItem()==null?"":chartMarketSpinner.getSelectedItem().toString();}
void toggleChartFullscreen(){
chartFullscreen=!chartFullscreen;
if(appHeader!=null)appHeader.setVisibility(chartFullscreen?View.GONE:View.VISIBLE);
if(mainNav!=null)mainNav.setVisibility(chartFullscreen?View.GONE:View.VISIBLE);if(chartQuickBar!=null)chartQuickBar.setVisibility(chartFullscreen?View.GONE:(chartPage!=null&&chartPage.getVisibility()==View.VISIBLE?View.VISIBLE:View.GONE));
if(chartStatus!=null)chartStatus.setVisibility(chartFullscreen?View.GONE:View.VISIBLE);
if(fullscreenButton!=null)fullscreenButton.setText(chartFullscreen?"⤢":"⛶");
if(appRoot!=null)appRoot.setPadding(chartFullscreen?0:dp(16),chartFullscreen?0:dp(16),chartFullscreen?0:dp(16),chartFullscreen?0:dp(24));
int screenH=getResources().getDisplayMetrics().heightPixels;
if(pages!=null){LinearLayout.LayoutParams pp=(LinearLayout.LayoutParams)pages.getLayoutParams();pp.height=chartFullscreen?screenH:-2;pages.setLayoutParams(pp);}
if(chartPage!=null){LinearLayout.LayoutParams cp=(LinearLayout.LayoutParams)chartPage.getLayoutParams();cp.height=chartFullscreen?screenH:-2;chartPage.setLayoutParams(cp);}
if(chartView!=null){LinearLayout.LayoutParams vp=(LinearLayout.LayoutParams)chartView.getLayoutParams();vp.height=chartFullscreen?Math.max(dp(220),screenH-dp(82)):dp(535);chartView.setLayoutParams(vp);chartView.requestLayout();}
int flags=chartFullscreen?(View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY):0;
getWindow().getDecorView().setSystemUiVisibility(flags);
if(mainScroll!=null)mainScroll.post(()->mainScroll.scrollTo(0,0));
}
void loadChart(){
final long requestId=++chartLoadRequestId;
if(chartView==null||chartSymbol().isEmpty()){if(chartStatus!=null)chartStatus.setText("Waiting for Arcus market list…");return;}
final String symbol=chartSymbol(),tf=chartTfSpinner.getSelectedItem().toString();updateChartQuickBar();chartView.setSymbol(symbol);chartStatus.setText("Loading "+symbol+" · "+tf+" candles…");
new Thread(()->{HttpURLConnection c=null;try{
long to=System.currentTimeMillis()*1000L;URL u=new URL("https://api.arcus.xyz/v1/candles?market="+java.net.URLEncoder.encode(symbol,"UTF-8")+"&timeframe="+tf+"&to="+to+"&countback=500");
c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setUseCaches(false);c.setRequestProperty("Accept","application/json");
int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);
if(code<200||code>=300)throw new Exception("Arcus API HTTP "+code+": "+out.toString("UTF-8"));
JSONObject response=new JSONObject(out.toString("UTF-8"));JSONArray arr=response.optJSONArray("candles");if(arr==null)throw new Exception("No candles field in Arcus response");
ArrayList<ChartView.Candle> candles=new ArrayList<>();for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o==null)continue;try{candles.add(new ChartView.Candle(o.optLong("openTime"),Double.parseDouble(o.getString("open")),Double.parseDouble(o.getString("high")),Double.parseDouble(o.getString("low")),Double.parseDouble(o.getString("close")),o.optDouble("volume",o.optDouble("baseVolume",0))));}catch(Exception ignored){}}
Collections.sort(candles,(a,b1)->Long.compare(a.time,b1.time));if(candles.isEmpty())throw new Exception("No candle data returned");
runOnUiThread(()->{if(requestId!=chartLoadRequestId||!symbol.equals(chartSymbol())||!tf.equals(chartTfSpinner.getSelectedItem().toString()))return;chartView.setSymbol(symbol);chartView.setCandles(candles);chartStatus.setText(symbol+" · "+tf+" · "+candles.size()+" candles");updateChartAlertLines();if(!pendingAlertSymbol.isEmpty()&&pendingAlertSymbol.equalsIgnoreCase(symbol)&&pendingAlertTarget>0){chartView.setTriggeredAlertPrice(pendingAlertTarget);pendingAlertSymbol="";pendingAlertTarget=0;}});
}catch(Exception e){String msg=e.getMessage()==null?"Chart loading failed":e.getMessage();runOnUiThread(()->{if(requestId==chartLoadRequestId)chartStatus.setText("Chart error: "+msg);});}finally{if(c!=null)c.disconnect();}}).start();
}
void addChartAlert(double price){
String symbol=chartSymbol();if(symbol.isEmpty()||price<=0)return;
new AlertDialog.Builder(this).setTitle("Add Alert").setMessage(symbol+"\\nTarget price: "+String.format(Locale.US,"%.8f",price))
.setNegativeButton("Cancel",null).setPositiveButton("Add Alert",(d,w)->{try{JSONArray a=levels();JSONObject o=new JSONObject();o.put("symbol",symbol);o.put("price",price);o.put("mode",1);o.put("created",System.currentTimeMillis());o.put("enabled",true);a.put(o);save(a);updateChartAlertLines();Toast.makeText(this,"Alert added at "+price,Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Could not save alert",Toast.LENGTH_SHORT).show();}}).show();
}

void updateChartAlertLines(){if(chartView==null)return;ArrayList<Double> prices=new ArrayList<>();JSONArray a=levels();String sym=chartSymbol();for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol")))prices.add(o.optDouble("price",0));}chartView.setAlertPrices(prices);}
void showChartAlertActions(int chartIndex){try{JSONArray a=levels();String sym=chartSymbol();int found=-1,n=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol"))){if(n==chartIndex){found=i;break;}n++;}}if(found<0)return;final int index=found;new AlertDialog.Builder(this).setTitle("Chart alert").setItems(new String[]{"Edit alert","Delete alert"},(d,w)->{if(w==0)editLevel(index);else{JSONArray old=levels(),next=new JSONArray();for(int i=0;i<old.length();i++)if(i!=index)next.put(old.opt(i));save(next);renderLevels();updateChartAlertLines();}}).setNegativeButton("Cancel",null).show();}catch(Exception ignored){}}
void moveChartAlert(int chartIndex,double price){try{JSONArray a=levels();String sym=chartSymbol();int found=-1,n=0;for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&o.optBoolean("enabled",true)&&sym.equalsIgnoreCase(o.optString("symbol"))){if(n==chartIndex){found=i;break;}n++;}}if(found<0)return;JSONObject o=a.getJSONObject(found);o.put("price",price);o.put("created",System.currentTimeMillis());a.put(found,o);save(a);updateChartAlertLines();Toast.makeText(this,"Alert moved to "+String.format(Locale.US,"%.6f",price),Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}
