double readPrice(JSONObject o){Object v=o.has("markPrice")&&!o.isNull("markPrice")?o.opt("markPrice"):o.opt("oraclePrice");try{return v==null?0:Double.parseDouble(v.toString());}catch(Exception e){return 0;}}
