JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}void save(JSONArray a){getSharedPreferences(PREF,0).edit().putString("levels",a.toString()).apply();}
String selected(){return marketSpinner==null||marketSpinner.getSelectedItem()==null?"":marketSpinner.getSelectedItem().toString();}
void filterMarkets(){String q=searchBox.getText().toString().trim().toLowerCase(Locale.ROOT),old=selected();shownNames.clear();for(String n:allNames)if((q.isEmpty()||n.toLowerCase(Locale.ROOT).contains(q))&&(!favoritesOnly||isFavorite(n)))shownNames.add(n);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,shownNames));int p=shownNames.indexOf(old);if(p>=0)marketSpinner.setSelection(p);updatePrice();}
JSONObject find(JSONObject d,String symbol){if(symbol==null||symbol.isEmpty())return null;Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null&&(symbol.equalsIgnoreCase(key)||symbol.equalsIgnoreCase(o.optString("marketDisplayName"))||symbol.equalsIgnoreCase(o.optString("symbol"))||symbol.equalsIgnoreCase(o.optString("marketId"))))return o;}return null;}
void refreshMarkets(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty()){status.setText("●  Waiting for market data…");return;}JSONObject d=new JSONObject(raw);ArrayList<String> fresh=new ArrayList<>();Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null){String n=o.optString("marketDisplayName","").trim();if(n.isEmpty())n=o.optString("symbol","").trim();if(n.isEmpty())n=key;if(!fresh.contains(n))fresh.add(n);}}Collections.sort(fresh,String.CASE_INSENSITIVE_ORDER);if(!fresh.equals(allNames)){allNames.clear();allNames.addAll(fresh);filterMarkets();if(chartMarketSpinner!=null){String oldChart=chartSymbol();chartNames.clear();chartNames.addAll(allNames);chartMarketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,chartNames));int cp=chartNames.indexOf(oldChart);if(cp>=0)chartMarketSpinner.setSelection(cp);updateChartQuickBar();updateChartAlertLines();if(!pendingAlertSymbol.isEmpty()){int ai=chartNames.indexOf(pendingAlertSymbol);if(ai>=0){chartMarketSpinner.setSelection(ai);loadChart();}}}}updatePrice();long u=getSharedPreferences(PREF,0).getLong("markets_updated",0);status.setText("●  "+allNames.size()+" markets · updated "+Math.max(0,(System.currentTimeMillis()-u)/1000)+"s ago");updateChartAlertLines();if(marketPage!=null&&marketPage.getVisibility()==View.VISIBLE)renderMarketRows();}catch(Exception e){if(status!=null)status.setText("Market data error: "+e.getMessage());}}
